package io.github.jesterportfolio.hearth.economy;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.jesterportfolio.hearth.economy.EconomyContent.*;
import static io.github.jesterportfolio.hearth.economy.EconomyEngine.*;

class EconomyReportTest {
    private Properties settings(){try(var r=new java.io.InputStreamReader(Objects.requireNonNull(getClass().getResourceAsStream("/economy-demo.properties")),java.nio.charset.StandardCharsets.UTF_8)){var p=new Properties();p.load(r);return p;}catch(Exception e){throw new AssertionError(e);}}
    private final Properties p=settings();private final EconomyContent c=EconomyContent.parse(p);private final EconomyShop shop=EconomyShop.parse(p,c);private final EconomyReport.Definition definition=EconomyReport.parse(p,c,shop);
    private State state(long tick,List<Shipment> shipments,List<Active> events){return new State(tick,initial(c).markets(),shipments,events);}
    @Test void defaultsHideUnregisteredRegionsRoutesFacilitiesAndEvents(){var minimal=settings();minimal.keySet().removeIf(k->k.toString().startsWith("report-"));var d=EconomyReport.parse(minimal,c,shop);var view=d.project(c,state(2,List.of(),List.of(new Active(UUID.randomUUID(),"road_block",1,13))),"capital");assertEquals(1,view.regions().size());assertTrue(view.routes().isEmpty());assertTrue(view.facilities().isEmpty());assertTrue(view.events().isEmpty());assertThrows(IllegalArgumentException.class,()->d.project(c,initial(c),"mine"));}
    @Test void invalidPublicReferencesFailBeforeActivation(){for(var entry:Map.of("report-regions","capital,capital","report-goods","missing","report-routes","missing","report-facilities","missing","report-events","missing").entrySet()){var bad=settings();bad.setProperty(entry.getKey(),entry.getValue());assertThrows(IllegalArgumentException.class,()->EconomyReport.parse(bad,c,shop));}var hiddenEndpoint=settings();hiddenEndpoint.setProperty("report-regions","capital");assertThrows(IllegalArgumentException.class,()->EconomyReport.parse(hiddenEndpoint,c,shop));}
    @Test void statusAndPricesComeFromSameImmutableSnapshot(){var rows=new HashMap<>(initial(c).markets());rows.put(new Key("capital","iron_ingot"),new Market(10,310,5));rows.put(new Key("capital","iron_ore"),new Market(500,110,4));var s=new State(5,rows,List.of(),List.of());var view=definition.project(c,s,"capital");assertEquals(StockStatus.SHORTAGE,view.markets().getFirst().status());assertEquals(StockStatus.SURPLUS,view.markets().get(1).status());assertEquals(quote(c,"iron_ingot",rows.get(new Key("capital","iron_ingot")),1,true),view.markets().getFirst().ask());assertEquals(5,view.tick());assertEquals(10,s.markets().get(new Key("capital","iron_ingot")).stock());assertThrows(UnsupportedOperationException.class,()->view.markets().clear());}
    @Test void impossibleSideHasNoFalsePrice(){var rows=new HashMap<>(initial(c).markets());rows.put(new Key("capital","iron_ingot"),new Market(0,300,0));rows.put(new Key("capital","iron_ore"),new Market(MAX_STOCK,100,0));var view=definition.project(c,new State(0,rows,List.of(),List.of()),"capital");assertNull(view.markets().get(0).ask());assertNull(view.markets().get(1).bid());}
    @Test void shipmentsRemainSeparateFromMarketStockAndHaveNoRequestIdInDto(){var id=UUID.randomUUID();var pending=List.of(new Shipment(id,"ore_road","mine","capital","iron_ore",7,3),new Shipment(UUID.randomUUID(),"ore_road","mine","capital","iron_ore",5,5));var view=definition.project(c,state(1,pending,List.of()),"capital");var route=view.routes().getFirst();assertEquals(12,route.inTransit());assertEquals(2,route.shipments());assertEquals(2,route.nextArrival());assertEquals(200,view.markets().get(1).stock());assertFalse(view.toString().contains(id.toString()));}
    @Test void pendingAndActiveEventsUseEconomyClockExactly(){var event=new Active(UUID.randomUUID(),"road_block",1,13);var scheduled=definition.project(c,state(0,List.of(),List.of(event)),"capital");assertTrue(scheduled.events().getFirst().scheduled());assertEquals(1,scheduled.events().getFirst().startsIn());assertFalse(scheduled.routes().getFirst().blocked());var active=definition.project(c,state(1,List.of(),List.of(event)),"capital");assertFalse(active.events().getFirst().scheduled());assertEquals(12,active.events().getFirst().remaining());assertTrue(active.routes().getFirst().blocked());assertTrue(definition.project(c,state(13,List.of(),List.of(event)),"capital").events().isEmpty());}
    @Test void eventScopeAndUnlistedDetailsStayPrivate(){var event=new Active(UUID.randomUUID(),"demand_surge",1,13);assertTrue(definition.project(c,state(2,List.of(),List.of(event)),"mine").events().isEmpty());var privateSettings=settings();privateSettings.setProperty("report-events","");var privateDefinition=EconomyReport.parse(privateSettings,c,shop);var view=privateDefinition.project(c,state(2,List.of(),List.of(event)),"capital");assertTrue(view.events().isEmpty());assertFalse(view.toString().contains("demand_surge"));}
    @Test void facilityAndDemandUseExistingEngineRules(){var events=List.of(new Active(UUID.randomUUID(),"mine_collapse",1,25),new Active(UUID.randomUUID(),"demand_surge",1,13));var s=state(2,List.of(),events);assertEquals(0,definition.project(c,s,"mine").facilities().getFirst().capacity());var capital=definition.project(c,s,"capital");assertEquals(6,capital.markets().getFirst().demand());assertEquals(5,capital.facilities().getFirst().capacity());assertEquals(2,capital.facilities().getFirst().inputs().getFirst().units());assertEquals(200,capital.facilities().getFirst().inputs().getFirst().stock());assertEquals(6,demandFor(c,s,2,new Key("capital","iron_ingot")));}
    @Test void projectionNeverInitializesMissingOrCorruptData(){var rows=new HashMap<>(initial(c).markets());rows.remove(new Key("capital","iron_ore"));assertThrows(IllegalArgumentException.class,()->definition.project(c,new State(0,rows,List.of(),List.of()),"capital"));var bad=new Shipment(UUID.randomUUID(),"ore_road","capital","mine","iron_ore",1,3);assertThrows(IllegalArgumentException.class,()->definition.project(c,state(0,List.of(bad),List.of()),"capital"));}
    @Test void paginationIsBoundedAndEmptyIsValid(){assertTrue(EconomyReport.page(List.of(),0).isEmpty());assertThrows(IllegalArgumentException.class,()->EconomyReport.page(List.of(),1));var list=new ArrayList<Integer>();for(int i=0;i<91;i++)list.add(i);assertEquals(45,EconomyReport.page(list,1).size());assertEquals(List.of(90),EconomyReport.page(list,2));assertThrows(IllegalArgumentException.class,()->EconomyReport.page(list,-1));}
}
